function useAddComment(postId: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (text: string) => postComment(postId, text),
    onMutate: async (text) => {
      const previous = qc.getQueryData(["comments", postId]);
      qc.setQueryData(["comments", postId], (old: Comment[]) => [
        ...old,
        { id: "temp", text, author: "me" },
      ]);
      return { previous };
    },
    onError: (_e, _text, ctx) => {
      qc.setQueryData(["comments", postId], ctx.previous);
    },
  });
}

